//! The design tokens of uses.ink: colours, font stacks and the looks a theme wears, from
//! `token.toml`.
//!
//! The constants are generated by `cargo xtask token` into `generated.rs`; edit `token.toml`,
//! never the generated file.

#![no_std]

use core::fmt;

mod generated;

pub use generated::{Colour, Face, Look};

/// A colour, as eight-bit red, green and blue.
#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash)]
pub struct Rgb(pub u8, pub u8, pub u8);

impl fmt::Display for Rgb {
    /// `#rrggbb`, lower case.
    fn fmt(&self, out: &mut fmt::Formatter<'_>) -> fmt::Result {
        write!(out, "#{:02x}{:02x}{:02x}", self.0, self.1, self.2)
    }
}

/// What a colour of a [`Look`] is for. Every look gives each role a colour in each [`Scheme`], so
/// a theme's stylesheet can use any of them.
#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash)]
pub enum Role {
    /// Text.
    Ink,
    /// The page behind the text.
    Paper,
    /// Text that matters less: dates, captions, the footer.
    Muted,
    /// Rules and borders, which carry no meaning of their own.
    Line,
    /// The ground of code and callouts.
    Tint,
    /// Links and marks.
    Accent,
}

impl Role {
    /// Every role, in the order a look lists them.
    pub const ALL: [Self; 6] = [Self::Ink, Self::Paper, Self::Muted, Self::Line, Self::Tint, Self::Accent];

    /// Its name, which is also its CSS custom property without the `--`.
    pub const fn name(self) -> &'static str {
        match self {
            Self::Ink => "ink",
            Self::Paper => "paper",
            Self::Muted => "muted",
            Self::Line => "line",
            Self::Tint => "tint",
            Self::Accent => "accent",
        }
    }
}

/// The reader's setting a look has colours for.
#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash)]
pub enum Scheme {
    /// The default.
    Light,
    /// `prefers-color-scheme: dark`.
    Dark,
}

impl Scheme {
    /// Both, light first.
    pub const ALL: [Self; 2] = [Self::Light, Self::Dark];
}

/// A kind of token, as a name asks for one.
#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash)]
pub enum Kind {
    /// A [`Colour`].
    Colour,
    /// A [`Face`].
    Face,
    /// A [`Look`].
    Look,
}

impl fmt::Display for Kind {
    fn fmt(&self, out: &mut fmt::Formatter<'_>) -> fmt::Result {
        out.write_str(match self {
            Self::Colour => "colour",
            Self::Face => "face",
            Self::Look => "look",
        })
    }
}

/// A name that is not a token.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct Unknown<'a> {
    /// What kind of token was asked for.
    pub kind: Kind,
    /// The name asked for.
    pub name: &'a str,
    /// The names there are.
    pub known: &'static [&'static str],
}

impl fmt::Display for Unknown<'_> {
    fn fmt(&self, out: &mut fmt::Formatter<'_>) -> fmt::Result {
        write!(out, "no {} named `{}`; the {}s are ", self.kind, self.name, self.kind)?;
        for (i, name) in self.known.iter().enumerate() {
            let sep = match i {
                0 => "",
                i if i + 1 == self.known.len() => " and ",
                _ => ", ",
            };
            write!(out, "{sep}`{name}`")?;
        }
        Ok(())
    }
}

impl core::error::Error for Unknown<'_> {}
